    def exact_keys(
        names: Iterable[str],
        overrides: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        properties = {name: {} for name in names}
        if overrides:
            properties.update(overrides)
        return {
            "additionalProperties": False,
            "properties": properties,
            "required": list(properties),
            "type": "object",
        }

